# owner: platform
import unittest

from hourglass.gaps import find_gaps
from hourglass.models import Span

OPEN = Span(9 * 60, 17 * 60)


class FindGapsTests(unittest.TestCase):
    def test_gap_in_the_middle(self):
        worked = [Span(9 * 60, 12 * 60), Span(13 * 60, 17 * 60)]
        self.assertEqual(find_gaps(worked, OPEN), ["gap 12:00-13:00 (60 min)"])

    def test_nothing_worked_is_one_gap(self):
        self.assertEqual(find_gaps([], OPEN), ["gap 09:00-17:00 (480 min)"])

    def test_edges_and_overlaps(self):
        worked = [Span(600, 700), Span(650, 800)]
        self.assertEqual(
            find_gaps(worked, OPEN),
            ["gap 09:00-10:00 (60 min)", "gap 13:20-17:00 (220 min)"]
        )

    def test_full_cover_has_no_gaps(self):
        self.assertEqual(find_gaps([Span(540, 1020)], OPEN), [])

    def test_span_outside_opening_hours_raises(self):
        with self.assertRaises(ValueError):
            find_gaps([Span(480, 600)], OPEN)
